const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
const API_BASE = String(window.NIRO_CONFIG?.API_BASE || '').replace(/\/$/, '');
const apiUrl = path => { if (!API_BASE && (location.hostname.endsWith('.netlify.app') || location.hostname.endsWith('.netlify.live'))) throw new Error('Configure API_BASE em config.js com a URL HTTPS do backend Niro Chat.'); return `${API_BASE}/api${path}`; };
const assetUrl = path => path && path.startsWith('/') && API_BASE ? `${API_BASE}${path}` : (path || '');
const state={token:localStorage.getItem('niro_token')||'',user:null,communities:[],community:null,detail:null,channel:null,ws:null,friends:[],friendFilter:'all',dmUser:null,dmTimer:null,searchTimer:null};
const api=async(path,opts={})=>{const headers={...(opts.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;if(opts.body&&!(opts.body instanceof FormData))headers['Content-Type']='application/json';let res=await fetch(apiUrl(path),{...opts,headers});let data;try{data=await res.json()}catch{data={detail:'Resposta inválida do servidor'}}if(!res.ok)throw new Error(data.detail||'Ocorreu um erro');return data};
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.classList.toggle('error',error);el.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.add('hidden'),3200)}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function avatarHTML(user,extra=''){const name=user.display_name||user.username||'?';return `<div class="user-avatar ${extra}">${user.avatar?`<img src="${escapeHtml(assetUrl(user.avatar))}" alt="">`:escapeHtml(name.trim().slice(0,1).toUpperCase()||'?')}</div>`}
function timeLabel(ts){try{return new Date(ts*1000).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}catch{return ''}}
function setAuthMode(mode){const reg=mode==='register';$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#register-fields').classList.toggle('hidden',!reg);$('#login-label').classList.toggle('hidden',reg);$('#auth-title').textContent=reg?'Crie seu espaço.':'Bom te ver de novo.';$('#auth-subtitle').textContent=reg?'Sua próxima comunidade começa com uma conta.':'Entre para continuar suas conversas.';$('#auth-submit').innerHTML=reg?'Criar minha conta <span>↗</span>':'Entrar na conta <span>↗</span>';$('#auth-form').dataset.mode=mode;$('#auth-form').elements.password.autocomplete=reg?'new-password':'current-password'}
$$('.tab').forEach(b=>b.addEventListener('click',()=>setAuthMode(b.dataset.mode)));
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),reg=e.currentTarget.dataset.mode==='register';const payload=reg?{username:f.get('username').trim(),email:f.get('email').trim(),password:f.get('password'),display_name:f.get('display_name').trim()}:{login:f.get('login').trim(),password:f.get('password')};try{const r=await api(reg?'/register':'/login',{method:'POST',body:JSON.stringify(payload)});state.token=r.token;state.user=r.user;localStorage.setItem('niro_token',r.token);await enterApp()}catch(err){toast(err.message,true)}});
async function enterApp(){try{state.user=await api('/me');$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');renderUser();await loadCommunities();await loadFriends();showView('home')}catch(e){logout(false)}}
function logout(show=true){if(state.ws)state.ws.close();state.ws=null;state.token='';state.user=null;localStorage.removeItem('niro_token');$('#app').classList.add('hidden');$('#auth').classList.remove('hidden');if(show)toast('Você saiu da sua conta.')}
function applyPreferences(){const p=state.user?.settings||{};document.documentElement.style.setProperty('--accent',/^#[0-9a-fA-F]{6}$/.test(p.accent_color||'')?p.accent_color:'#b6f36b');document.body.dataset.theme=p.theme==='darker'?'darker':'dark';document.body.classList.toggle('compact-mode',!!p.compact_mode);document.body.classList.toggle('reduced-motion',!!p.reduced_motion);document.documentElement.style.setProperty('--user-font-size',p.font_size==='small'?'11px':p.font_size==='large'?'14px':'12px')}
function renderUser(){if(!state.user)return;applyPreferences();$('#bottom-name').textContent=state.user.display_name;$('#bottom-status').textContent=state.user.status;$('#bottom-avatar').innerHTML=state.user.avatar?`<img src="${escapeHtml(assetUrl(state.user.avatar))}">`:escapeHtml(state.user.display_name.slice(0,1).toUpperCase());$('#rail-profile').innerHTML=state.user.avatar?`<img src="${escapeHtml(assetUrl(state.user.avatar))}">`:escapeHtml(state.user.display_name.slice(0,1).toUpperCase())}
function showView(view){['home','community','showcase','friends','dm','profile'].forEach(v=>$('#view-'+v).classList.toggle('hidden',v!==view));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view||(view==='dm'&&b.dataset.view==='friends')));const titles={home:['Início','/ visão geral','✳'],community:[state.detail?.community?.name||'Comunidade','/ comunidade','#'],showcase:[state.detail?.community?.name||'Comunidade','/ vitrine','✦'],friends:['Amigos','/ sua rede','♧'],dm:[state.dmUser?.display_name||'Mensagem direta','/ mensagens','↗'],profile:['Configurações','/ sua conta','⚙']};const t=titles[view]||titles.home;$('#crumb-name').textContent=t[0];$('#crumb-detail').textContent=t[1];$('#crumb-icon').textContent=t[2];$('#sidebar-title').textContent=(view==='community'||view==='showcase')?(state.detail?.community?.name||'Comunidade'):view==='friends'?'Amigos':view==='profile'?'Configurações':'Mensagens';if(view==='profile')fillProfile()}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
$('#open-profile').onclick=$('#bottom-settings').onclick=$('#header-profile').onclick=$('#rail-profile').onclick=()=>showView('profile');
$('#hero-friends').onclick=$('#home-add-friend').onclick=$('#friend-add-top').onclick=()=>{showView('friends');$('#global-search').focus();toast('Use a busca à esquerda para encontrar pessoas pelo nome de usuário.')};
$('#open-create').onclick=$('#sidebar-add').onclick=$('#hero-create').onclick=$('#empty-create').onclick=()=>openCreateCommunity();
$('#open-join').onclick=$('#home-join').onclick=()=>openJoinCommunity();
$('#logout-btn').onclick=()=>logout();
async function loadCommunities(){state.communities=await api('/communities');renderCommunities()}
function renderCommunities(){const list=$('#community-list'),icons=$('#community-icons'),cards=$('#home-communities');list.innerHTML='';icons.innerHTML='';cards.innerHTML='';if(!state.communities.length){cards.innerHTML='<div class="empty-card"><span>✳</span><b>Seu próximo espaço começa aqui.</b><p>Crie uma comunidade ou entre em uma usando um convite.</p><button class="secondary" id="empty-create2">Criar meu espaço</button></div>';$('#empty-create2').onclick=openCreateCommunity}else state.communities.forEach(co=>{const item=document.createElement('button');item.className='community-list-item'+(state.community?.id===co.id?' active':'');item.innerHTML=`<span class="community-mini">${escapeHtml(co.icon||co.name.slice(0,1).toUpperCase())}</span><span class="community-label">${escapeHtml(co.name)}</span><span class="community-unread">${co.member_count||1}</span>`;item.onclick=()=>openCommunity(co.id);list.append(item);const ic=document.createElement('button');ic.className='community-icon'+(state.community?.id===co.id?' selected':'');ic.title=co.name;ic.innerHTML=escapeHtml(co.icon||co.name.slice(0,1).toUpperCase());ic.onclick=()=>openCommunity(co.id);icons.append(ic);const card=document.createElement('div');card.className='community-card';card.innerHTML=`${co.settings?.showcase_banner_url?`<img class="community-card-banner" src="${escapeHtml(co.settings.showcase_banner_url)}" alt="">`:''}<div class="community-card-icon">${escapeHtml(co.icon||co.name.slice(0,1).toUpperCase())}</div><b>${escapeHtml(co.settings?.showcase_title||co.name)}</b><p>${escapeHtml(co.settings?.showcase_description||co.description||'Sua comunidade')}</p><button class="secondary">Abrir espaço ↗</button>`;card.querySelector('button').onclick=()=>openCommunity(co.id);cards.append(card)});}
async function openCommunity(id){try{if(state.ws){state.ws.close();state.ws=null}state.community=state.communities.find(c=>c.id===id)||{id};state.detail=await api('/communities/'+id);state.community=state.detail.community;renderCommunities();showView('community');$('#community-name').textContent=state.detail.community.name;$('#community-description').textContent=state.detail.community.description||'';$('#community-emblem').textContent=state.detail.community.icon||state.detail.community.name.slice(0,1).toUpperCase();$('#community-emblem').style.background=state.detail.community.settings?.community_color||'';$('#community-members-count').textContent=state.detail.members.length+' membros';$('#members-total').textContent=state.detail.members.length;renderChannels();renderMembers();if(state.detail.channels.length){const ch=state.detail.channels.find(x=>x.kind==='text')||state.detail.channels[0];await openChannel(ch.id)}else{$('#message-list').innerHTML='<div class="no-results">Nenhum canal disponível.</div>'}}catch(e){toast(e.message,true)}}
function renderChannels(){
 const text=$('#channel-list');text.innerHTML='';if(!state.detail)return;
 const me=state.detail.members.find(m=>m.id===state.user.id);const customIds=(me?.custom_roles||[]).map(x=>x.id);const canManage=canPerm('manage_channels');
 const channels=state.detail.channels.filter(ch=>ch.kind==='text').sort((a,b)=>Number(a.settings?.sort_order||a.position||0)-Number(b.settings?.sort_order||b.position||0)||a.id-b.id);const folders=state.detail.folders||[];const collapsedKey='niro_folders_'+state.community.id;let collapsed={};try{collapsed=JSON.parse(localStorage.getItem(collapsedKey)||'{}')}catch{}
 const makeChannel=(ch)=>{const wrap=document.createElement('div');wrap.className='channel-row';wrap.draggable=canManage;wrap.dataset.channelId=ch.id;wrap.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/niro-channel',String(ch.id));e.dataTransfer.effectAllowed='move';wrap.classList.add('dragging')});wrap.addEventListener('dragend',()=>wrap.classList.remove('dragging'));const b=document.createElement('button');b.className='channel-item'+(state.channel?.id===ch.id?' active':'');b.innerHTML=`<span class="channel-hash">#</span><span>${escapeHtml(ch.name)}</span>`;b.onclick=()=>openChannel(ch.id);wrap.append(b);if(canManage){const settings=document.createElement('button');settings.className='channel-settings';settings.textContent='⚙';settings.title='Configurar canal';settings.onclick=e=>{e.stopPropagation();openChannelSettings(ch)};wrap.append(settings);const del=document.createElement('button');del.className='channel-delete';del.textContent='×';del.title='Excluir canal';del.onclick=async e=>{e.stopPropagation();if(!confirm(`Excluir o canal ${ch.name} e todas as mensagens dele?`))return;try{await api(`/channels/${ch.id}`,{method:'DELETE'});toast('Canal excluído');await openCommunity(state.community.id)}catch(err){toast(err.message,true)}};wrap.append(del)}return wrap};
 const makeDrop=(el,folderId)=>{el.addEventListener('dragover',e=>{if(canManage&&e.dataTransfer.types.includes('text/niro-channel')){e.preventDefault();el.classList.add('drop-target')}});el.addEventListener('dragleave',()=>el.classList.remove('drop-target'));el.addEventListener('drop',async e=>{el.classList.remove('drop-target');if(!canManage)return;const id=Number(e.dataTransfer.getData('text/niro-channel'));if(!id)return;e.preventDefault();try{await api(`/channels/${id}/folder`,{method:'PATCH',body:JSON.stringify({folder_id:folderId})});const ch=state.detail.channels.find(x=>x.id===id);if(ch)ch.folder_id=folderId;renderChannels();toast(folderId?'Canal movido para a pasta':'Canal removido da pasta')}catch(err){toast(err.message,true)}})};
 folders.forEach(folder=>{const box=document.createElement('section');box.className='channel-folder';box.dataset.folderId=folder.id;makeDrop(box,folder.id);const head=document.createElement('div');head.className='folder-heading';const isCollapsed=!!collapsed[folder.id];head.innerHTML=`<button class="folder-toggle" aria-expanded="${!isCollapsed}">${isCollapsed?'▸':'▾'}</button><button class="folder-name"><span class="folder-icon">▰</span><strong>${escapeHtml(folder.name)}</strong></button><span class="folder-count">${channels.filter(ch=>Number(ch.folder_id)===folder.id).length}</span>${canManage?'<button class="folder-more" title="Opções da pasta">•••</button>':''}`;head.querySelector('.folder-toggle').onclick=()=>{collapsed[folder.id]=!collapsed[folder.id];localStorage.setItem(collapsedKey,JSON.stringify(collapsed));renderChannels()};head.querySelector('.folder-name').onclick=()=>{collapsed[folder.id]=!collapsed[folder.id];localStorage.setItem(collapsedKey,JSON.stringify(collapsed));renderChannels()};if(canManage){head.querySelector('.folder-more').onclick=()=>openFolderOptions(folder)}box.append(head);if(!isCollapsed){const body=document.createElement('div');body.className='folder-channels';channels.filter(ch=>Number(ch.folder_id)===folder.id).forEach(ch=>body.append(makeChannel(ch)));makeDrop(body,folder.id);box.append(body)}text.append(box)});
 const ungrouped=document.createElement('div');ungrouped.className='ungrouped-channels';makeDrop(ungrouped,null);channels.filter(ch=>ch.folder_id==null||!folders.some(f=>f.id===Number(ch.folder_id))).forEach(ch=>ungrouped.append(makeChannel(ch)));if(ungrouped.children.length||!folders.length)text.append(ungrouped);
}
function openFolderOptions(folder){openModal(`<h2>Editar pasta</h2><p>O nome em negrito ajuda a separar visualmente os assuntos da comunidade.</p><form id="folder-edit-form" class="modal-form"><label>Nome da pasta<input name="name" required maxlength="50" value="${escapeHtml(folder.name)}"></label><button class="primary" type="submit">Salvar nome</button><button class="danger-button" id="folder-delete" type="button">Excluir pasta (manter canais)</button></form>`);$('#folder-edit-form').onsubmit=async e=>{e.preventDefault();const name=new FormData(e.currentTarget).get('name').trim();try{await api(`/communities/${state.community.id}/folders/${folder.id}`,{method:'PATCH',body:JSON.stringify({name})});closeModal();await openCommunity(state.community.id);toast('Pasta atualizada')}catch(err){toast(err.message,true)}};$('#folder-delete').onclick=async()=>{if(!confirm(`Excluir a pasta ${folder.name}? Os canais serão mantidos fora de pastas.`))return;try{await api(`/communities/${state.community.id}/folders/${folder.id}`,{method:'DELETE'});closeModal();await openCommunity(state.community.id);toast('Pasta excluída; canais preservados')}catch(err){toast(err.message,true)}}}

function canPerm(permission){if(!state.detail)return false;if(state.detail.my_role==='Owner')return true;const settings=state.detail.community.settings||{},matrix=settings.role_permission_matrix||{},order=settings.role_order||['builtin:Owner','builtin:Admin',...(state.detail.roles||[]).map(r=>'custom:'+r.id),'builtin:Moderator','builtin:Member'];const me=state.detail.members.find(m=>m.id===state.user.id);const keys=[`builtin:${state.detail.my_role}`,...(me?.custom_roles||[]).map(r=>'custom:'+r.id)].sort((a,b)=>order.indexOf(a)-order.indexOf(b));const key=keys[0],idx=order.indexOf(key);const fallback=()=>{if(key==='builtin:Admin')return true;if(['builtin:Member','builtin:Moderator'].includes(key))return ['read_messages','send_messages'].includes(permission);if(key?.startsWith('custom:')){const r=(state.detail.roles||[]).find(x=>'custom:'+x.id===key);return !!r?.permissions?.[permission]}return false};const own=matrix[key]&&matrix[key][permission]!==undefined?!!matrix[key][permission]:fallback();if(!own)return false;for(const higher of order.slice(1,idx)){if(matrix[higher]&&matrix[higher][permission]===false)return false}return true}
function renderMembers(){
 const wrap=$('#members-list');wrap.innerHTML='';
 const groups={Owner:[],Admin:[],Moderator:[],Member:[]};state.detail.members.forEach(m=>(groups[m.role]||groups.Member).push(m));
 const order=state.detail.community.settings?.role_order||['builtin:Owner','builtin:Admin',...(state.detail.roles||[]).map(r=>'custom:'+r.id),'builtin:Moderator','builtin:Member'];
 const roleKeyForMember=member=>{const keys=[`builtin:${member.role}`,...(member.custom_roles||[]).map(r=>'custom:'+r.id)];return keys.sort((a,b)=>{const ai=order.indexOf(a),bi=order.indexOf(b);return (ai<0?9999:ai)-(bi<0?9999:bi)})[0]};
 Object.entries(groups).forEach(([role,users])=>{if(!users.length)return;const title=document.createElement('div');title.className='member-group-title';title.textContent=role==='Owner'?'DONO':role.toUpperCase()+'S';wrap.append(title);
  users.forEach(m=>{const row=document.createElement('div');row.className='member-row';row.innerHTML=`${avatarHTML(m)}<div class="member-info"><b>${escapeHtml(m.display_name)}</b><span>@${escapeHtml(m.username)}</span>${(m.custom_roles||[]).map(r=>`<small class="custom-role-tag" style="color:${escapeHtml(r.color)}">${escapeHtml(r.name)}</small>`).join('')}</div>${role==='Owner'?'<span class="role-dot"></span>':''}`;
   const actor=state.detail.members.find(x=>x.id===state.user.id)||{role:state.detail.my_role},actorKey=roleKeyForMember(actor),targetKey=roleKeyForMember(m),canTarget=order.indexOf(actorKey)>=0&&order.indexOf(targetKey)>=0&&order.indexOf(actorKey)<order.indexOf(targetKey);
   const hasAnyModeration=canPerm('manage_members')||canPerm('manage_roles')||canPerm('timeout_members')||canPerm('ban_members')||canPerm('kick_members');
   if(hasAnyModeration&&m.id!==state.user.id&&m.role!=='Owner'&&canTarget){const controls=document.createElement('div');controls.className='member-controls';
    if(canPerm('manage_members')){const sel=document.createElement('select');sel.className='role-menu';sel.innerHTML=['Member','Moderator','Admin'].map(r=>`<option value="${r}" ${r===m.role?'selected':''}>${r}</option>`).join('');sel.title='Cargo principal';sel.onchange=async()=>{const previous=m.role;try{await api(`/communities/${state.community.id}/members/${m.id}/role`,{method:'PATCH',body:JSON.stringify({role:sel.value})});toast('Cargo atualizado e salvo');await openCommunity(state.community.id)}catch(e){toast(e.message,true);sel.value=previous}};controls.append(sel)}
    if(canPerm('manage_roles')&&state.detail.roles?.length){const custom=document.createElement('select');custom.className='role-menu custom-role-select';custom.innerHTML='<option value="">+ Cargo</option>'+state.detail.roles.filter(r=>order.indexOf('custom:'+r.id)>order.indexOf(actorKey)).map(r=>`<option value="${r.id}">${escapeHtml(r.name)}</option>`).join('');custom.title='Atribuir cargo personalizado';custom.onchange=async()=>{if(!custom.value)return;try{await api(`/communities/${state.community.id}/members/${m.id}/roles`,{method:'PUT',body:JSON.stringify({role_id:Number(custom.value)})});toast('Cargo personalizado atribuído');await openCommunity(state.community.id)}catch(e){toast(e.message,true)}};controls.append(custom)}
    const actionButton=(label,title,handler)=>{const btn=document.createElement('button');btn.className='member-remove';btn.textContent=label;btn.title=title;btn.onclick=handler;controls.append(btn)};
    if(canPerm('timeout_members'))actionButton('⏱','Castigar temporariamente',async()=>{const mins=prompt(`Por quantos minutos silenciar @${m.username}?`,'10');if(mins===null)return;try{await api(`/communities/${state.community.id}/members/${m.id}/timeout`,{method:'POST',body:JSON.stringify({minutes:Number(mins)})});toast('Membro castigado temporariamente')}catch(e){toast(e.message,true)}});
    if(canPerm('ban_members'))actionButton('⛔','Banir membro',async()=>{if(!confirm(`Banir @${m.username} desta comunidade?`))return;const reason=prompt('Motivo do banimento (opcional):','')||'';try{await api(`/communities/${state.community.id}/members/${m.id}/ban`,{method:'POST',body:JSON.stringify({reason})});toast('Membro banido');await openCommunity(state.community.id)}catch(e){toast(e.message,true)}});
    if(canPerm('kick_members')||canPerm('manage_members'))actionButton('×','Remover membro',async()=>{if(!confirm(`Remover @${m.username} da comunidade?`))return;try{await api(`/communities/${state.community.id}/members/${m.id}`,{method:'DELETE'});toast('Membro removido');await openCommunity(state.community.id)}catch(e){toast(e.message,true)}});
    if(controls.children.length)row.append(controls)
   }
   wrap.append(row)
  })
 });
}
async function openChannel(id){const ch=state.detail.channels.find(x=>x.id===id);if(!ch)return;state.channel=ch;renderChannels();$('#channel-title').textContent=ch.name;$('#channel-topic').textContent=ch.settings?.topic||ch.settings?.description||'Mensagens da comunidade';$('#channel-title').style.color=ch.settings?.channel_color||'';$('#message-input').placeholder='Mensagem em #'+ch.name;const readOnly=!!ch.settings?.read_only&&!canPerm('manage_channels');$('#message-input').disabled=readOnly;$('#message-form').querySelector('button[type=submit]').disabled=readOnly;$('#message-input').title=readOnly?'Este canal está somente para leitura':'';$('#message-list').innerHTML=`<div class="chat-welcome"><div class="welcome-hash">#</div><h2>Bem-vindo a #${escapeHtml(ch.name)}!</h2><p>${escapeHtml(ch.settings?.channel_welcome||'Esse é o começo de algo bom.')}</p></div>`;try{const msgs=await api('/channels/'+id+'/messages');$('#message-list').innerHTML='';if(!msgs.length)renderWelcome();else msgs.forEach(renderMessage);scrollMessages();connectWS(id)}catch(e){toast(e.message,true)}}
function renderWelcome(){if($('#message-list').children.length)return;const ch=state.channel||{};$('#message-list').innerHTML=`<div class="chat-welcome"><div class="welcome-hash">#</div><h2>Bem-vindo a #${escapeHtml(ch.name||'canal')}!</h2><p>${escapeHtml(ch.settings?.channel_welcome||'Esse é o começo de algo bom.')}</p></div>`}
function renderMessage(m){const list=$('#message-list');if(list.querySelector('.chat-welcome'))list.innerHTML='';const node=document.createElement('div');node.className='message'+(m.message_type&&m.message_type!=='chat'?' message-'+m.message_type:'');node.dataset.id=m.id;let content=escapeHtml(m.content);let label='';if(m.message_type==='announcement')label='<span class="message-type-label">📣 ANÚNCIO</span>';else if(m.message_type==='suggestion')label='<span class="message-type-label">✦ IDEIA DA COMUNIDADE</span>';else if(m.message_type==='poll'){label='<span class="message-type-label">▤ ENQUETE</span>';try{const poll=JSON.parse(m.content);content=`<div class="poll-card"><b>${escapeHtml(poll.question||'Enquete')}</b><div class="poll-options">${(poll.options||[]).map((o,i)=>`<button type="button" class="poll-option" data-option="${i}">${escapeHtml(o)}</button>`).join('')}</div><small class="poll-total">Carregando votos…</small></div>`}catch{}}node.innerHTML=`${avatarHTML({display_name:m.display_name,avatar:m.avatar})}<div class="message-body">${label}<div class="message-meta"><b>${escapeHtml(m.display_name||m.username)}</b><time>${timeLabel(m.created_at)}</time></div><div class="message-content">${content}</div></div>`;if(m.user_id===state.user.id||canPerm('delete_messages')){const actions=document.createElement('div');actions.className='message-actions';const del=document.createElement('button');del.type='button';del.textContent='Apagar';del.title='Apagar mensagem';del.onclick=async()=>{if(!confirm('Apagar esta mensagem?'))return;try{await api(`/messages/${m.id}`,{method:'DELETE'});node.remove();toast('Mensagem apagada')}catch(e){toast(e.message,true)}};actions.append(del);node.append(actions)}list.append(node);if(m.message_type==='poll'){const refresh=async()=>{try{const results=await api(`/messages/${m.id}/poll`);const options=node.querySelectorAll('.poll-option');options.forEach((button,i)=>{const count=results.votes[i]||0,percent=results.total?Math.round(count/results.total*100):0;button.innerHTML=`<span>${escapeHtml(results.options[i])}</span><span class=\"poll-result-count\">${count} · ${percent}%</span>`;button.classList.toggle('voted',results.my_vote===i);button.style.setProperty('--poll-percent',percent+'%');button.disabled=false;button.onclick=async()=>{try{await api(`/messages/${m.id}/poll/vote`,{method:'POST',body:JSON.stringify({option_index:i})});await refresh()}catch(err){toast(err.message,true)}}});const total=node.querySelector('.poll-total');if(total)total.textContent=`${results.total} voto(s) · você pode alterar seu voto`}catch{}};node.querySelectorAll('.poll-option').forEach(b=>{b.disabled=true});refresh()}}
function scrollMessages(){const el=$('#message-list');el.scrollTop=el.scrollHeight}
function connectWS(id){if(state.ws)state.ws.close();const proto=API_BASE?(API_BASE.startsWith('https:')?'wss':'ws'):(location.protocol==='https:'?'wss':'ws');const host=API_BASE?new URL(API_BASE).host:location.host;const ws=new WebSocket(`${proto}://${host}/ws/channels/${id}?token=${encodeURIComponent(state.token)}`);state.ws=ws;ws.onopen=()=>{$('#connection-text').textContent='Ao vivo';$('.connection-dot').style.background='var(--accent)'};ws.onmessage=e=>{try{const m=JSON.parse(e.data);if(m.error){toast(m.error,true);return}if(m.deleted_id){const deleted=$('#message-list').querySelector(`[data-id="${m.deleted_id}"]`);if(deleted)deleted.remove();return}if(!m.id)return;if(!$('#message-list').querySelector(`[data-id="${m.id}"]`)){renderMessage(m);scrollMessages()}}catch{}};ws.onclose=()=>{if(state.ws===ws){$('#connection-text').textContent='Reconecte ao canal';$('.connection-dot').style.background='var(--red)'}}}
$('#message-form').addEventListener('submit',async e=>{e.preventDefault();const input=$('#message-input'),content=input.value.trim(),type=$('#message-type').value;if(!content||!state.channel)return;let finalContent=content;if(type==='poll'){const options=prompt('Digite 2 a 6 opções separadas por vírgula:');if(!options)return;const opts=options.split(',').map(x=>x.trim()).filter(Boolean).slice(0,6);if(opts.length<2){toast('Uma enquete precisa de pelo menos duas opções.',true);return}finalContent=JSON.stringify({question:content,options:opts})}input.value='';$('#message-type').value='chat';try{if(state.ws&&state.ws.readyState===WebSocket.OPEN){state.ws.send(JSON.stringify({content:finalContent,message_type:type}));return}const m=await api('/channels/'+state.channel.id+'/messages',{method:'POST',body:JSON.stringify({content:finalContent,message_type:type})});renderMessage(m);scrollMessages()}catch(err){toast(err.message,true);input.value=content}});
$('#toggle-members').onclick=()=>{$('#members-panel').classList.toggle('members-visible')};
// Mobile drawer for channel navigation; desktop keeps the persistent three-column layout.
const mobileChannelButton=document.createElement('button');mobileChannelButton.type='button';mobileChannelButton.className='mobile-channel-toggle';mobileChannelButton.setAttribute('aria-label','Abrir canais');mobileChannelButton.title='Abrir canais';mobileChannelButton.textContent='☰';$('.chat-header')?.prepend(mobileChannelButton);
mobileChannelButton.addEventListener('click',()=>$('#view-community').classList.toggle('mobile-channels-open'));
$('#channel-list')?.addEventListener('click',e=>{if(e.target.closest('button'))$('#view-community').classList.remove('mobile-channels-open')});
$('#copy-invite').onclick=async()=>{try{const r=await api(`/communities/${state.community.id}/invite`);const link=location.origin+'/?invite='+r.invite_code;await navigator.clipboard.writeText(link);toast('Link de convite copiado!')}catch(e){openInviteModal()}};
$('#community-menu').onclick=$('#community-settings').onclick=()=>{if(!state.detail)return;openModal(`<h2>Configurações da comunidade</h2><p>Personalize nome, ícone e descrição. As opções avançadas são salvas no banco de dados.</p><form id="community-edit-form" class="modal-form"><label>Nome<input name="name" required maxlength="60" value="${escapeHtml(state.detail.community.name)}"></label><label>Ícone (emoji opcional)<input name="icon" maxlength="8" value="${escapeHtml(state.detail.community.icon||'')}" placeholder="✳"></label><label>Descrição<textarea name="description" maxlength="300" rows="3">${escapeHtml(state.detail.community.description||'')}</textarea></label><button class="primary" type="submit">Salvar nome e aparência</button></form><div class="modal-form">${canPerm('manage_community')?'<button class="secondary" id="community-advanced">30 opções de comunidade</button>':''}<button class="secondary" id="show-invite">Ver link de convite</button>${canPerm('manage_roles')?'<button class="secondary" id="manage-roles">Gerenciar cargos e permissões</button>':''}${canPerm('ban_members')?'<button class="secondary" id="manage-bans">Gerenciar banimentos</button>':''}${state.detail.my_role==='Owner'?'<button class="danger-button" id="delete-community">Excluir comunidade</button>':''}</div>`);$('#community-edit-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/communities/${state.community.id}`,{method:'PATCH',body:JSON.stringify({name:f.get('name'),description:f.get('description'),icon:f.get('icon')||''})});closeModal();await loadCommunities();await openCommunity(state.community.id);toast('Comunidade atualizada')}catch(err){toast(err.message,true)}};if($('#community-advanced'))$('#community-advanced').onclick=openCommunityAdvancedSettings;$('#show-invite').onclick=openInviteModal;if($('#manage-roles'))$('#manage-roles').onclick=openRoleManager;if($('#manage-bans'))$('#manage-bans').onclick=openBanManager;if($('#delete-community'))$('#delete-community').onclick=async()=>{if(!confirm('Excluir esta comunidade e todo o seu conteúdo? Esta ação não pode ser desfeita.'))return;try{await api(`/communities/${state.community.id}`,{method:'DELETE'});closeModal();state.community=null;state.detail=null;state.channel=null;await loadCommunities();showView('home');toast('Comunidade excluída')}catch(e){toast(e.message,true)}}};
$('#add-channel').onclick=()=>{if(!['Owner','Admin'].includes(state.detail?.my_role)){toast('Somente Owner/Admin pode criar canais.',true);return}openModal(`<h2>Criar canal de texto</h2><p>Organize a comunidade em canais dedicados a cada assunto. O Niro Chat não inclui chat de voz.</p><form id="channel-create-form" class="modal-form"><label>Nome do canal<input name="name" required maxlength="50" pattern="[A-Za-z0-9_-]+" placeholder="ex.: novidades"></label><button class="primary" type="submit">Criar canal</button></form>`);$('#channel-create-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/communities/${state.community.id}/channels`,{method:'POST',body:JSON.stringify({name:f.get('name'),kind:'text'})});closeModal();await openCommunity(state.community.id);toast('Canal criado')}catch(err){toast(err.message,true)}}};
$('#add-folder').onclick=()=>{if(!['Owner','Admin'].includes(state.detail?.my_role)){toast('Somente Owner/Admin pode criar pastas.',true);return}openModal(`<h2>Criar pasta de canais</h2><p>Use pastas como <b>FA-ARTS</b>, ANÚNCIOS ou PROJETOS. Depois arraste canais para dentro delas.</p><form id="folder-create-form" class="modal-form"><label>Nome da pasta<input name="name" required maxlength="50" placeholder="ex.: FA-ARTS"></label><button class="primary" type="submit">Criar pasta</button></form>`);$('#folder-create-form').onsubmit=async e=>{e.preventDefault();const name=new FormData(e.currentTarget).get('name').trim();try{await api(`/communities/${state.community.id}/folders`,{method:'POST',body:JSON.stringify({name})});closeModal();await openCommunity(state.community.id);toast('Pasta criada! Agora arraste canais para ela.')}catch(err){toast(err.message,true)}}};
async function openShowcase(){
 const co=state.detail.community,settings=co.settings||{};showView('showcase');
 const root=$('#view-showcase');root.innerHTML=`<div class="showcase-page"><div class="showcase-topline"><button class="secondary" id="showcase-back">← Voltar à comunidade</button><span class="eyebrow">NIRO COMMUNITY SPOTLIGHT</span>${canPerm('manage_community')?'<button class="primary" id="showcase-edit">✎ Editar vitrine</button>':''}</div><section class="showcase-hero ${settings.showcase_banner_url?'has-banner':''}" ${settings.showcase_banner_url?`style="--showcase-image:url('${escapeHtml(settings.showcase_banner_url).replace(/'/g,'%27')}')"`:''}><div class="showcase-hero-overlay"></div><div class="showcase-hero-content"><div class="showcase-community-icon">${escapeHtml(co.icon||co.name.slice(0,1).toUpperCase())}</div><span class="eyebrow">COMUNIDADE EM DESTAQUE</span><h1>${escapeHtml(settings.showcase_title||co.name)}</h1><p>${escapeHtml(settings.showcase_description||co.description||'Um espaço para reunir pessoas, ideias e criações.')}</p><div class="showcase-hero-actions"><button class="primary" id="showcase-chat">Entrar nas conversas ↗</button><button class="secondary" id="showcase-gallery-jump">Ver galeria de criações</button></div><div class="showcase-stats"><span><b>${state.detail.members.length}</b> membros</span><span><b>✦</b> comunidade</span><span><b>NIRO</b> spotlight</span></div></div><div class="showcase-decoration"><span>✳</span><i></i><i></i><i></i></div></section><section class="showcase-content-section"><div class="showcase-section-heading"><div><span class="eyebrow">FIQUE POR DENTRO</span><h2>Próximos eventos</h2><p>O que está acontecendo nesta comunidade.</p></div><button class="secondary" id="showcase-all-events">Ver todos os eventos ↗</button></div><div id="showcase-events" class="showcase-event-grid"><div class="feature-empty">Carregando agenda…</div></div></section><section class="showcase-bottom-grid"><article class="showcase-promo-card"><span class="showcase-promo-icon">▧</span><div><span class="eyebrow">CRIATIVIDADE</span><h2>Feito pela comunidade.</h2><p>Artes, modelos, vídeos e ideias dos membros em um só lugar.</p></div><button class="primary" id="showcase-open-gallery">Explorar criações ↗</button></article><article class="showcase-promo-card showcase-promo-alt"><span class="showcase-promo-icon">#</span><div><span class="eyebrow">CONVERSAS</span><h2>Encontre seu espaço.</h2><p>Canais organizados por assunto, projetos e interesses.</p></div><button class="secondary" id="showcase-open-chats">Abrir canais ↗</button></article></section><footer class="showcase-footer">NIRO CHAT <span>·</span> Seu espaço, com a sua identidade.</footer></div>`;
 $('#showcase-back').onclick=()=>showView('community');$('#showcase-chat').onclick=()=>showView('community');$('#showcase-open-chats').onclick=()=>showView('community');$('#showcase-gallery-jump').onclick=$('#showcase-open-gallery').onclick=openGallery;$('#showcase-all-events').onclick=openEvents;if($('#showcase-edit'))$('#showcase-edit').onclick=openShowcaseEditor;
 try{const events=await api(`/communities/${state.community.id}/events`),box=$('#showcase-events');if(!box)return;const upcoming=events.filter(e=>new Date(e.starts_at).getTime()>=Date.now()).slice(0,3);box.innerHTML=upcoming.length?'':'<div class="feature-empty">Ainda não há eventos futuros. Volte em breve para ver as novidades.</div>';upcoming.forEach(ev=>{const date=new Date(ev.starts_at),card=document.createElement('article');card.className='showcase-event-card';card.innerHTML=`<div class="showcase-event-date"><span>${escapeHtml(Number.isNaN(date.getTime())?'—':date.toLocaleDateString('pt-BR',{month:'short'}).replace('.',''))}</span><b>${escapeHtml(Number.isNaN(date.getTime())?'—':date.toLocaleDateString('pt-BR',{day:'2-digit'}))}</b></div><div class="showcase-event-info"><span class="eyebrow">EVENTO DA COMUNIDADE</span><h3>${escapeHtml(ev.title)}</h3><p>${escapeHtml(ev.description||'Uma atividade para a comunidade.')}</p><small>${escapeHtml(Number.isNaN(date.getTime())?ev.starts_at:date.toLocaleString('pt-BR'))}${ev.location?' · '+escapeHtml(ev.location):''}</small></div>`;box.append(card)})}catch(e){const box=$('#showcase-events');if(box)box.innerHTML='<div class="feature-empty">Não foi possível carregar os eventos.</div>'}
}
function openShowcaseEditor(){const co=state.detail.community,settings=co.settings||{};openModal(`<div class="feature-modal-heading"><span class="eyebrow">IDENTIDADE DA COMUNIDADE</span><h2>Editar vitrine</h2><p>Esta informação aparece em uma página de destaque.</p></div>${settings.showcase_banner_url?`<img class="showcase-banner" src="${escapeHtml(settings.showcase_banner_url)}" alt="Banner da comunidade">`:''}<form id="showcase-form" class="modal-form"><label>Título de destaque<input name="showcase_title" maxlength="80" value="${escapeHtml(settings.showcase_title||co.name)}"></label><label>Descrição<textarea name="showcase_description" maxlength="500" rows="4">${escapeHtml(settings.showcase_description||co.description||'')}</textarea></label><label>URL do banner<input name="showcase_banner_url" type="url" value="${escapeHtml(settings.showcase_banner_url||'')}" placeholder="https://..."></label><button class="primary" type="submit">Salvar vitrine</button></form>`);$('#showcase-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/communities/${state.community.id}/showcase`,{method:'PATCH',body:JSON.stringify({showcase_title:f.get('showcase_title'),showcase_description:f.get('showcase_description'),showcase_banner_url:f.get('showcase_banner_url')})});closeModal();await openCommunity(state.community.id);await openShowcase();toast('Vitrine atualizada')}catch(err){toast(err.message,true)}}}

function openEvents(){const id=state.community.id;openModal('<div class="feature-modal-heading"><span class="eyebrow">AGENDA DA COMUNIDADE</span><h2>Eventos</h2><p>Organize lançamentos, encontros, campeonatos e atividades.</p></div><div id="events-list" class="feature-list">Carregando eventos…</div>'+(canPerm('manage_community')?'<form id="event-form" class="modal-form"><h3>Novo evento</h3><label>Nome do evento<input name="title" required maxlength="100" placeholder="ex.: Noite de jogos"></label><label>Data e hora<input name="starts_at" type="datetime-local" required></label><label>Local ou link<input name="location" maxlength="160" placeholder="Opcional"></label><label>Descrição<textarea name="description" rows="2" maxlength="1000"></textarea></label><button class="primary" type="submit">Criar evento</button></form>':''));const load=async()=>{try{const events=await api(`/communities/${id}/events`),box=$('#events-list');box.innerHTML=events.length?'':'<div class="feature-empty">Ainda não há eventos. Crie o primeiro para reunir a comunidade.</div>';events.forEach(ev=>{const row=document.createElement('article');row.className='event-card';const date=new Date(ev.starts_at);row.innerHTML=`<div class="event-date"><b>${Number.isNaN(date.getTime())?'—':date.toLocaleDateString('pt-BR',{day:'2-digit'})}</b><span>${Number.isNaN(date.getTime())?'':date.toLocaleDateString('pt-BR',{month:'short'})}</span></div><div class="event-info"><b>${escapeHtml(ev.title)}</b><span>${Number.isNaN(date.getTime())?escapeHtml(ev.starts_at):date.toLocaleString('pt-BR')}</span><p>${escapeHtml(ev.description||'')}${ev.location?'<br>'+escapeHtml(ev.location):''}</p></div>${canPerm('manage_community')?`<button class="danger-button event-delete" data-id="${ev.id}">Excluir</button>`:''}`;box.append(row)});$$('.event-delete').forEach(b=>b.onclick=async()=>{try{await api(`/communities/${id}/events/${b.dataset.id}`,{method:'DELETE'});await load()}catch(err){toast(err.message,true)}})}catch(e){$('#events-list').textContent=e.message}};load();if($('#event-form'))$('#event-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),date=new Date(f.get('starts_at'));try{await api(`/communities/${id}/events`,{method:'POST',body:JSON.stringify({title:f.get('title'),starts_at:date.toISOString(),location:f.get('location'),description:f.get('description')})});e.currentTarget.reset();await load();toast('Evento criado')}catch(err){toast(err.message,true)}}}
function openGallery(){const id=state.community.id;openModal('<div class="feature-modal-heading"><span class="eyebrow">CRIAÇÕES DA COMUNIDADE</span><h2>Galeria</h2><p>Compartilhe artes, vídeos, modelos, teorias e outras criações. Use um link público da mídia.</p></div><div id="gallery-list" class="gallery-grid">Carregando galeria…</div><form id="gallery-form" class="modal-form"><h3>Publicar criação</h3><label>Título<input name="title" required maxlength="100" placeholder="Nome da criação"></label><label>Link da imagem ou criação<input name="media_url" type="url" required placeholder="https://..."></label><label>Descrição<textarea name="description" maxlength="1000" rows="2"></textarea></label><button class="primary" type="submit">Publicar na galeria</button></form>');const load=async()=>{try{const items=await api(`/communities/${id}/gallery`),box=$('#gallery-list');box.innerHTML=items.length?'':'<div class="feature-empty">A galeria está vazia. Publica a primeira criação!</div>';items.forEach(item=>{const card=document.createElement('article');card.className='gallery-card';card.innerHTML=`<a href="${escapeHtml(item.media_url)}" target="_blank" rel="noopener"><img src="${escapeHtml(item.media_url)}" alt="${escapeHtml(item.title)}" loading="lazy" onerror="this.style.display='none'"></a><div class="gallery-card-body"><b>${escapeHtml(item.title)}</b><p>${escapeHtml(item.description||'')}</p><small>por ${escapeHtml(item.creator_name||'membro')}</small>${item.created_by===state.user.id||canPerm('manage_community')?`<button class="danger-button gallery-delete" data-id="${item.id}">Excluir</button>`:''}</div>`;box.append(card)});$$('.gallery-delete').forEach(b=>b.onclick=async()=>{try{await api(`/communities/${id}/gallery/${b.dataset.id}`,{method:'DELETE'});await load()}catch(err){toast(err.message,true)}})}catch(e){$('#gallery-list').textContent=e.message}};load();$('#gallery-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/communities/${id}/gallery`,{method:'POST',body:JSON.stringify({title:f.get('title'),media_url:f.get('media_url'),description:f.get('description')})});e.currentTarget.reset();await load();toast('Criação publicada na galeria')}catch(err){toast(err.message,true)}}}
$('#open-showcase').onclick=openShowcase;$('#open-events').onclick=openEvents;$('#open-gallery').onclick=openGallery;
function canManageRoleUI(role){if(state.detail.my_role==='Owner')return true;const order=state.detail.community.settings?.role_order||['builtin:Owner','builtin:Admin',...(state.detail.roles||[]).map(r=>'custom:'+r.id),'builtin:Moderator','builtin:Member'];const actor=state.detail.members.find(m=>m.id===state.user.id)||{role:state.detail.my_role};const actorKeys=[`builtin:${actor.role}`,...(actor.custom_roles||[]).map(r=>'custom:'+r.id)].sort((a,b)=>order.indexOf(a)-order.indexOf(b));const actorRank=order.indexOf(actorKeys[0]),targetRank=order.indexOf('custom:'+role.id);return canPerm('manage_roles')&&targetRank>actorRank}
function openRoleManager(){
 if(!state.community||!state.detail)return;
 const perms=[['manage_community','Configurar comunidade'],['manage_channels','Criar e excluir canais'],['manage_roles','Gerenciar cargos'],['manage_members','Gerenciar membros'],['send_messages','Enviar mensagens'],['read_messages','Ler mensagens'],['create_invites','Criar convites'],['manage_messages','Gerenciar mensagens'],['delete_messages','Apagar mensagens de outros'],['timeout_members','Castigar membros'],['kick_members','Remover membros'],['ban_members','Banir membros'],['bypass_slowmode','Ignorar modo lento']];
 const roleRows=(state.detail.roles||[]).map(r=>`<div class="role-manager-row"><span class="role-color" style="background:${escapeHtml(r.color)}"></span><div class="role-manager-info"><b>${escapeHtml(r.name)}</b><small>${Object.keys(r.permissions||{}).filter(k=>r.permissions[k]).length} permissões</small></div>${canManageRoleUI(r)?`<button class="secondary role-edit" data-role="${r.id}">Editar</button><button class="secondary role-settings" data-role="${r.id}">20 opções</button><button class="danger-button role-delete" data-role="${r.id}">Excluir</button>`:'<small class="muted">Cargo superior</small>'}</div>`).join('');
 openModal(`<h2>Cargos e permissões</h2><p>Crie cargos personalizados, escolha a cor e defina as ações permitidas. A hierarquia completa e as permissões globais são configuradas pelo dono.</p>${state.detail.my_role==='Owner'?'<button class="primary hierarchy-open" id="open-role-hierarchy">☷ Configurar hierarquia e permissões de todos os cargos</button>':''}<div class="role-manager-list">${roleRows||'<div class="no-results">Nenhum cargo personalizado ainda.</div>'}</div><form id="role-form" class="modal-form"><h3 id="role-form-title">Criar cargo</h3><input type="hidden" name="role_id" value=""><label>Nome do cargo<input name="name" required minlength="2" maxlength="32" placeholder="ex.: Desenvolvedor"></label><label>Cor do cargo<input name="color" type="color" value="#b6f36b"></label><div class="permission-grid">${perms.map(([k,label])=>`<label class="permission-option"><input type="checkbox" name="perm_${k}" ${['read_messages','send_messages'].includes(k)?'checked':''}>${label}</label>`).join('')}</div><button class="primary" type="submit">Salvar cargo</button><button class="secondary hidden" type="button" id="role-cancel-edit">Cancelar edição</button></form>`);
 if($('#open-role-hierarchy'))$('#open-role-hierarchy').onclick=openRoleHierarchy;
 const form=$('#role-form');
 function resetRoleForm(){form.reset();form.elements.role_id.value='';form.elements.color.value='#b6f36b';$('#role-form-title').textContent='Criar cargo';$('#role-cancel-edit').classList.add('hidden');form.querySelector('button[type="submit"]').textContent='Criar cargo';}
 form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),permissions={};perms.forEach(([k])=>permissions[k]=f.get('perm_'+k)==='on');const payload={name:f.get('name'),color:f.get('color'),permissions};const roleId=f.get('role_id');try{await api(`/communities/${state.community.id}/roles${roleId?'/'+roleId:''}`,{method:roleId?'PATCH':'POST',body:JSON.stringify(payload)});toast(roleId?'Cargo atualizado e salvo':'Cargo criado e salvo');await openCommunity(state.community.id);openRoleManager()}catch(e){toast(e.message,true)}};
 $('#role-cancel-edit').onclick=resetRoleForm;
 $$('.role-edit').forEach(btn=>btn.onclick=()=>{const r=state.detail.roles.find(x=>String(x.id)===btn.dataset.role);if(!r)return;form.elements.role_id.value=r.id;form.elements.name.value=r.name;form.elements.color.value=r.color||'#b6f36b';perms.forEach(([k])=>form.elements['perm_'+k].checked=!!r.permissions?.[k]);$('#role-form-title').textContent='Editar cargo';$('#role-cancel-edit').classList.remove('hidden');form.querySelector('button[type="submit"]').textContent='Salvar alterações';form.scrollIntoView({behavior:'smooth',block:'nearest'})});
 $$('.role-delete').forEach(btn=>btn.onclick=async()=>{const r=state.detail.roles.find(x=>String(x.id)===btn.dataset.role);if(!r||!confirm(`Excluir o cargo ${r.name}?`))return;try{await api(`/communities/${state.community.id}/roles/${r.id}`,{method:'DELETE'});toast('Cargo excluído');await openCommunity(state.community.id);openRoleManager()}catch(e){toast(e.message,true)}});
 $$('.role-settings').forEach(btn=>btn.onclick=()=>{const r=state.detail.roles.find(x=>String(x.id)===btn.dataset.role);if(r)openRoleAdvancedSettings(r)})
}
function openCreateCommunity(){openModal(`<h2>Crie uma comunidade</h2><p>Um espaço seu para reunir pessoas, organizar canais e compartilhar ideias.</p><form id="create-community-form" class="modal-form"><label>Nome da comunidade<input name="name" required minlength="2" maxlength="60" placeholder="ex.: Niro Works"></label><label>Ícone (emoji opcional)<input name="icon" maxlength="8" placeholder="✳"></label><label>Descrição<textarea name="description" maxlength="300" rows="3" placeholder="Qual é a ideia desse espaço?"></textarea></label><button class="primary" type="submit">Criar comunidade ↗</button></form>`);$('#create-community-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const co=await api('/communities',{method:'POST',body:JSON.stringify({name:f.get('name'),description:f.get('description'),icon:f.get('icon')||''})});closeModal();await loadCommunities();await openCommunity(co.id);toast('Comunidade criada!')}catch(err){toast(err.message,true)}}}
function openJoinCommunity(){openModal(`<h2>Entrar em uma comunidade</h2><p>Cole o código ou link de convite que alguém compartilhou com você.</p><form id="join-community-form" class="modal-form"><label>Link ou código de convite<input name="invite" required placeholder="https://... ou código"></label><button class="primary" type="submit">Entrar na comunidade</button></form>`);$('#join-community-form').onsubmit=async e=>{e.preventDefault();let invite=new FormData(e.currentTarget).get('invite').trim();try{if(invite.includes('invite='))invite=new URL(invite).searchParams.get('invite');else if(invite.includes('/'))invite=invite.split('/').filter(Boolean).pop();const r=await api('/communities/join/'+encodeURIComponent(invite),{method:'POST'});closeModal();await loadCommunities();await openCommunity(r.community_id);toast('Você entrou na comunidade!')}catch(err){toast(err.message,true)}}}
async function openBanManager(){const id=state.community.id;openModal('<div class="feature-modal-heading"><span class="eyebrow">MODERAÇÃO</span><h2>Banimentos da comunidade</h2><p>Gerencie quem não pode voltar a entrar nesta comunidade.</p></div><div id="bans-list" class="feature-list">Carregando banimentos…</div>');const load=async()=>{try{const bans=await api(`/communities/${id}/bans`),box=$('#bans-list');box.innerHTML=bans.length?'':'<div class="feature-empty">Não há membros banidos.</div>';bans.forEach(ban=>{const row=document.createElement('article');row.className='event-card';row.innerHTML=`<div class="event-info"><b>${escapeHtml(ban.display_name||ban.username)}</b><span>@${escapeHtml(ban.username)}</span><p>${escapeHtml(ban.reason||'Nenhum motivo informado')}</p></div><button class="secondary unban-member" data-id="${ban.user_id}">Desbanir</button>`;box.append(row)});$$('.unban-member').forEach(btn=>btn.onclick=async()=>{if(!confirm('Remover o banimento deste usuário?'))return;try{await api(`/communities/${id}/bans/${btn.dataset.id}`,{method:'DELETE'});toast('Banimento removido');await load()}catch(e){toast(e.message,true)}})}catch(e){$('#bans-list').textContent=e.message}};load()}
function openInviteModal(){if(!state.community)return;api(`/communities/${state.community.id}/invite`).then(r=>{const link=location.origin+'/?invite='+r.invite_code;openModal(`<h2>Convide pessoas</h2><p>Compartilhe este link com quem você quer trazer para a comunidade.</p><div class="invite-display"><input id="invite-link" readonly value="${escapeHtml(link)}"><button class="primary" id="copy-invite-modal">Copiar</button></div><p class="modal-note">Qualquer pessoa com o link poderá entrar. Compartilhe apenas com quem você confia.</p>`);$('#copy-invite-modal').onclick=async()=>{try{await navigator.clipboard.writeText(link);toast('Convite copiado!')}catch{$('#invite-link').select();document.execCommand('copy');toast('Convite copiado!')}}}).catch(e=>toast(e.message,true))}
