function settingValue(def,values){return values?.[def[0]]!==undefined?values[def[0]]:def[3]}
function settingsFields(defs,values){return `<div class="advanced-setting-grid">${defs.map(d=>{const [key,label,type,def,opts]=d,v=settingValue(d,values);let input='';if(type==='checkbox')input=`<input type="checkbox" name="${key}" ${v?'checked':''}>`;else if(type==='select')input=`<select name="${key}">${opts.map(o=>`<option value="${escapeHtml(o[0])}" ${String(v)===String(o[0])?'selected':''}>${escapeHtml(o[1])}</option>`).join('')}</select>`;else if(type==='textarea')input=`<textarea name="${key}" rows="2">${escapeHtml(v??'')}</textarea>`;else input=`<input type="${type}" name="${key}" value="${escapeHtml(v??'')}" ${type==='number'?'min="0"':''}>`;return `<label class="advanced-setting ${type==='checkbox'?'check-setting':''}"><span>${escapeHtml(label)}</span>${input}</label>`}).join('')}</div>`}
function readSettingsForm(form,defs){const out={};defs.forEach(d=>{const el=form.elements[d[0]];if(!el)return;out[d[0]]=d[2]==='checkbox'?el.checked:d[2]==='number'?(Number(el.value)||0):el.value});return out}
function openSettingsEditor(title,description,defs,current,onSave){openModal(`<h2>${escapeHtml(title)}</h2><p>${escapeHtml(description)}</p><form id="advanced-settings-form" class="modal-form advanced-settings-form">${settingsFields(defs,current)}<button class="primary" type="submit">Salvar todas as opções</button></form>`);$('#advanced-settings-form').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button[type="submit"]');button.disabled=true;try{const settings=readSettingsForm(e.currentTarget,defs);await onSave(settings);closeModal();toast('Configurações salvas no banco de dados')}catch(err){toast(err.message,true)}finally{button.disabled=false}}}
function openProfileAdvancedSettings(){const current={...(state.user.settings||{}),dm_policy:state.user.dm_policy,friend_request_policy:state.user.friend_request_policy,profile_visibility:state.user.profile_visibility,show_activity:state.user.show_activity,allow_friend_requests:state.user.friend_request_policy!=='nobody',profile_visibility_detail:state.user.profile_visibility};const defs=PROFILE_SETTINGS.map(d=>d);openSettingsEditor('Configurações avançadas do perfil','30 opções persistidas para aparência, privacidade, mensagens e notificações. Foto e bio são configuradas na tela de perfil.',defs,current,async settings=>{state.user=await api('/me/settings',{method:'PATCH',body:JSON.stringify({settings})});renderUser();fillProfile()})}
function openCommunityAdvancedSettings(){const co=state.detail.community;openSettingsEditor('Configurações da comunidade','30 opções personalizáveis. As opções ficam salvas nesta comunidade e podem ser alteradas por quem tem permissão.',COMMUNITY_SETTINGS,co.settings||{},async settings=>{await api(`/communities/${state.community.id}/settings`,{method:'PATCH',body:JSON.stringify({settings})});await openCommunity(state.community.id)})}
function openChannelSettings(ch){const defs=CHANNEL_SETTINGS.map(d=>d[0]==='slowmode_role_key'?[d[0],d[1],d[2],d[3],[['all','Todos os membros'],...(state.detail.roles||[]).map(r=>['custom:'+r.id,r.name]),['builtin:Owner','Dono'],['builtin:Admin','Administrador'],['builtin:Moderator','Moderador'],['builtin:Member','Membro']]]:d);openSettingsEditor(`Configurações de #${ch.name}`,'21 opções do canal. Visibilidade, links e modo lento são aplicados pelo servidor. O modo lento pode afetar somente o cargo escolhido e os cargos abaixo dele.',defs,ch.settings||{},async settings=>{await api(`/channels/${ch.id}/settings`,{method:'PATCH',body:JSON.stringify({settings})});await openCommunity(state.community.id);if(state.channel?.id===ch.id)await openChannel(ch.id)})}
function openRoleHierarchy(){
 const settings=state.detail.community.settings||{},custom=state.detail.roles||[];
 const defaultOrder=['builtin:Owner','builtin:Admin',...custom.map(r=>'custom:'+r.id),'builtin:Moderator','builtin:Member'];
 let order=Array.isArray(settings.role_order)?settings.role_order.filter(k=>defaultOrder.includes(k)):defaultOrder;
 order=[...order,...defaultOrder.filter(k=>!order.includes(k))];order=order.filter(k=>k!=='builtin:Owner');order.unshift('builtin:Owner');order=order.filter(k=>k!=='builtin:Member');order.push('builtin:Member');
 const matrix=settings.role_permission_matrix||{};
 const permissionDefs=[['manage_community','Configurar comunidade'],['manage_channels','Configurar canais e pastas'],['manage_roles','Gerenciar cargos'],['manage_members','Gerenciar membros'],['send_messages','Enviar mensagens'],['read_messages','Ler mensagens'],['create_invites','Criar convites'],['manage_messages','Gerenciar mensagens'],['delete_messages','Apagar mensagens de outros'],['timeout_members','Castigar membros'],['kick_members','Remover membros'],['ban_members','Banir membros'],['pin_messages','Fixar mensagens'],['bypass_slowmode','Ignorar modo lento']];
 const labels={'builtin:Owner':'Dono','builtin:Admin':'Administrador','builtin:Moderator':'Moderador','builtin:Member':'Membro'};
 const titleFor=key=>key.startsWith('custom:')?(custom.find(r=>'custom:'+r.id===key)?.name||'Cargo personalizado'):labels[key]||key;
 const isChecked=(key,perm)=>{if(matrix[key]&&matrix[key][perm]!==undefined)return !!matrix[key][perm];if(key==='builtin:Admin')return true;if(['builtin:Member','builtin:Moderator'].includes(key))return ['read_messages','send_messages'].includes(perm);if(key.startsWith('custom:')){const r=custom.find(x=>'custom:'+x.id===key);return !!r?.permissions?.[perm]}return false};
 const render=()=>{
  const rows=order.map((key,i)=>{
   const isOwner=key==='builtin:Owner';
   const controls=isOwner?'<p class="hierarchy-owner-note">O dono sempre tem todas as permissões e não pode ser rebaixado.</p>':`<div class="hierarchy-permissions">${permissionDefs.map(([perm,label])=>`<label><input type="checkbox" data-role-key="${escapeHtml(key)}" data-permission="${perm}" ${isChecked(key,perm)?'checked':''}>${escapeHtml(label)}</label>`).join('')}</div>`;
   const note=isOwner?'Permissões absolutas do dono':(i===1?'Cargo administrativo':`Nível ${i+1} · limite de permissões para cargos inferiores`);
   return `<article class="hierarchy-role-card" data-key="${escapeHtml(key)}"><div class="hierarchy-role-top"><span class="hierarchy-rank">${i+1}</span><div class="hierarchy-role-name"><b>${escapeHtml(titleFor(key))}</b><small>${note}</small></div><div class="hierarchy-move"><button type="button" data-move="up" data-key="${escapeHtml(key)}" ${isOwner||i===1?'disabled':''} title="Mover para cima">↑</button><button type="button" data-move="down" data-key="${escapeHtml(key)}" ${isOwner||i===order.length-1?'disabled':''} title="Mover para baixo">↓</button></div></div>${controls}</article>`;
  }).join('');
  $('#hierarchy-rows').innerHTML=rows;
  $$('[data-move]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.key,idx=order.indexOf(key),target=btn.dataset.move==='up'?idx-1:idx+1;if(idx<=1&&target<idx||idx<0||target<1||target>=order.length)return;[order[idx],order[target]]=[order[target],order[idx]];render()});
 };
 openModal(`<div class="feature-modal-heading"><span class="eyebrow">PERMISSÕES DO SERVIDOR</span><h2>Hierarquia de cargos</h2><p>O topo tem mais autoridade. Uma permissão negada num nível superior funciona como limite para todos os cargos abaixo dele.</p></div><div id="hierarchy-rows" class="hierarchy-list"></div><div class="hierarchy-footer"><button class="secondary" id="hierarchy-cancel">Voltar</button><button class="primary" id="hierarchy-save">Salvar hierarquia e permissões</button></div>`);
 render();$('#hierarchy-cancel').onclick=openRoleManager;
 $('#hierarchy-save').onclick=async()=>{const permissions={};$$('[data-role-key][data-permission]').forEach(el=>{const key=el.dataset.roleKey;permissions[key]=permissions[key]||{};permissions[key][el.dataset.permission]=el.checked});try{await api(`/communities/${state.community.id}/roles/hierarchy`,{method:'PATCH',body:JSON.stringify({order,permissions})});await openCommunity(state.community.id);openRoleManager();toast('Hierarquia e permissões salvas')}catch(e){toast(e.message,true)}};
}
function openRoleAdvancedSettings(role){openSettingsEditor(`Configurações do cargo: ${role.name}`,'20 opções persistidas para identidade, posição, moderação e capacidades do cargo.',ROLE_SETTINGS,role.settings||{},async settings=>{await api(`/communities/${state.community.id}/roles/${role.id}/settings`,{method:'PATCH',body:JSON.stringify({settings})});await openCommunity(state.community.id)})}

function openModal(html){$('#modal-content').innerHTML=html;$('#modal-backdrop').classList.remove('hidden')}function closeModal(){$('#modal-backdrop').classList.add('hidden');$('#modal-content').innerHTML=''}$('#modal-close').onclick=closeModal;$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
$('#global-search').addEventListener('input',e=>{clearTimeout(state.searchTimer);const q=e.target.value.trim();if(q.length<2){$('#search-results').classList.add('hidden');$('#search-results').innerHTML='';return}state.searchTimer=setTimeout(async()=>{try{const results=await api('/users/search?q='+encodeURIComponent(q));const box=$('#search-results');box.innerHTML='';if(!results.length)box.innerHTML='<div class="search-result"><small>Nenhuma pessoa encontrada.</small></div>';results.forEach(u=>{const row=document.createElement('div');row.className='search-result';row.innerHTML=`${avatarHTML(u)}<div class="result-info"><b>${escapeHtml(u.display_name)}</b><small>@${escapeHtml(u.username)}</small></div>`;if(!u.friendship_status){const b=document.createElement('button');b.className='mini-add';b.textContent='＋';b.title='Enviar pedido';b.onclick=async()=>{try{const r=await api('/friends/request',{method:'POST',body:JSON.stringify({username:u.username})});toast(r.message);await loadFriends();b.disabled=true;b.textContent='✓';const status=row.querySelector('.search-status');if(status)status.textContent='Pedido enviado'}catch(err){toast(err.message,true)}};row.append(b)}else{const s=document.createElement('small');s.className='search-status';s.textContent=u.friendship_status==='accepted'?'Amigos':u.friendship_direction==='incoming'?'Pedido recebido':u.friendship_direction==='outgoing'?'Pedido enviado':'Pendente';row.append(s);if(u.friendship_direction==='incoming'){const a=document.createElement('button');a.className='mini-add';a.textContent='✓';a.title='Aceitar pedido';a.onclick=async()=>{try{await api(`/friends/${u.id}/accept`,{method:'POST'});await loadFriends();toast('Pedido aceito')}catch(err){toast(err.message,true)}};row.append(a)}}if(u.dm_policy==='everyone'&&u.friendship_status!=='accepted'){const dm=document.createElement('button');dm.className='mini-add search-dm';dm.textContent='↗';dm.title='Enviar mensagem privada';dm.onclick=()=>openDM(u);row.append(dm)}box.append(row)});box.classList.remove('hidden')}catch(err){toast(err.message,true)}},250)});
async function loadFriends(){state.friends=await api('/friends');const pending=state.friends.filter(f=>f.direction==='incoming').length;const outgoing=state.friends.filter(f=>f.direction==='outgoing').length;$('#friend-count').textContent=state.friends.filter(f=>f.friendship_status==='accepted').length;$('#incoming-count').textContent=pending;$('#outgoing-count').textContent=outgoing;renderFriends()}
$$('[data-friends]').forEach(b=>b.onclick=()=>{state.friendFilter=b.dataset.friends;$$('[data-friends]').forEach(x=>x.classList.toggle('active',x===b));renderFriends()});
function renderFriends(){
 const box=$('#friends-list');box.innerHTML='';
 let friends=state.friends.filter(f=>state.friendFilter==='incoming'?f.direction==='incoming':state.friendFilter==='outgoing'?f.direction==='outgoing':f.friendship_status==='accepted');
 if(!friends.length){box.innerHTML=`<div class="no-results">${state.friendFilter==='incoming'?'Você não tem pedidos recebidos pendentes.':state.friendFilter==='outgoing'?'Você não tem pedidos enviados pendentes.':'Ainda não há amigos. Use a busca para encontrar pessoas.'}</div>`;return}
 friends.forEach(f=>{const row=document.createElement('div');row.className='friend-row';row.innerHTML=`${avatarHTML(f)}<div class="friend-row-info"><b>${escapeHtml(f.display_name)}</b><span>@${escapeHtml(f.username)} · ${f.status==='online'?'Online':escapeHtml(f.status)}</span></div>`;const actions=document.createElement('div');actions.className='friend-actions';
  if(f.direction==='incoming'){const a=document.createElement('button');a.className='accept';a.textContent='Aceitar';a.onclick=async()=>{try{await api(`/friends/${f.id}/accept`,{method:'POST'});await loadFriends();toast('Pedido aceito e salvo')}catch(e){toast(e.message,true)}};actions.append(a)}
  else if(f.direction==='outgoing'){const label=document.createElement('span');label.className='pending-label';label.textContent='Aguardando resposta';actions.append(label)}
  else {const dm=document.createElement('button');dm.textContent='Mensagem';dm.onclick=()=>openDM(f);actions.append(dm)}
  const rem=document.createElement('button');rem.className='remove';rem.textContent=f.direction==='incoming'?'Recusar':f.direction==='outgoing'?'Cancelar':'Remover';rem.onclick=async()=>{try{await api(`/friends/${f.id}`,{method:'DELETE'});await loadFriends();toast(f.direction==='incoming'?'Pedido recusado':f.direction==='outgoing'?'Pedido cancelado':'Amizade removida')}catch(e){toast(e.message,true)}};actions.append(rem);row.append(actions);box.append(row)
 })
}
async function openDM(friend){state.dmUser=friend;showView('dm');$('#dm-name').textContent=friend.display_name;$('#dm-handle').textContent='@'+friend.username;$('#dm-avatar').innerHTML=friend.avatar?`<img src="${escapeHtml(friend.avatar)}">`:escapeHtml(friend.display_name.slice(0,1).toUpperCase());try{const msgs=await api('/dms/'+friend.id);$('#dm-messages').innerHTML='';if(!msgs.length)$('#dm-messages').innerHTML='<div class="no-results">Essa é sua primeira conversa com '+escapeHtml(friend.display_name)+'.</div>';msgs.forEach(m=>{const n=document.createElement('div');n.className='message';n.innerHTML=`${avatarHTML({display_name:m.display_name,avatar:m.avatar})}<div class="message-body"><div class="message-meta"><b>${escapeHtml(m.display_name)}</b><time>${timeLabel(m.created_at)}</time></div><div class="message-content">${escapeHtml(m.content)}</div></div>`;$('#dm-messages').append(n)});scrollMessages();clearInterval(state.dmTimer);state.dmTimer=setInterval(async()=>{if(state.dmUser?.id!==friend.id)return;try{const latest=await api('/dms/'+friend.id);const el=$('#dm-messages');if(latest.length!==el.querySelectorAll('.message').length){el.innerHTML='';latest.forEach(m=>{const n=document.createElement('div');n.className='message';n.innerHTML=`${avatarHTML({display_name:m.display_name,avatar:m.avatar})}<div class="message-body"><div class="message-meta"><b>${escapeHtml(m.display_name)}</b><time>${timeLabel(m.created_at)}</time></div><div class="message-content">${escapeHtml(m.content)}</div></div>`;el.append(n)});scrollMessages()}}catch{}},2500)}catch(e){toast(e.message,true)}}
$('#dm-form').onsubmit=async e=>{e.preventDefault();const input=$('#dm-input'),content=input.value.trim();if(!content||!state.dmUser)return;try{await api('/dms/'+state.dmUser.id,{method:'POST',body:JSON.stringify({content})});input.value='';const msgs=await api('/dms/'+state.dmUser.id);$('#dm-messages').innerHTML='';msgs.forEach(m=>{const n=document.createElement('div');n.className='message';n.innerHTML=`${avatarHTML({display_name:m.display_name,avatar:m.avatar})}<div class="message-body"><div class="message-meta"><b>${escapeHtml(m.display_name)}</b><time>${timeLabel(m.created_at)}</time></div><div class="message-content">${escapeHtml(m.content)}</div></div>`;$('#dm-messages').append(n)});scrollMessages()}catch(err){toast(err.message,true)}};
function fillProfile(){if(!state.user)return;$('#profile-display').value=state.user.display_name||'';$('#profile-username').value=state.user.username||'';$('#profile-bio').value=state.user.bio||'';$('#profile-status').value=state.user.status||'online';$('#profile-dm-policy').value=state.user.dm_policy||'friends';$('#profile-friend-policy').value=state.user.friend_request_policy||'everyone';$('#profile-visibility').value=state.user.profile_visibility||'everyone';$('#profile-show-activity').checked=state.user.show_activity!==false;$('#profile-avatar-preview').innerHTML=state.user.avatar?`<img src="${escapeHtml(assetUrl(state.user.avatar))}">`:escapeHtml(state.user.display_name.slice(0,1).toUpperCase())}
$('#profile-form').onsubmit=async e=>{e.preventDefault();try{state.user=await api('/me',{method:'PATCH',body:JSON.stringify({display_name:$('#profile-display').value,bio:$('#profile-bio').value,status:$('#profile-status').value,dm_policy:$('#profile-dm-policy').value,friend_request_policy:$('#profile-friend-policy').value,profile_visibility:$('#profile-visibility').value,show_activity:$('#profile-show-activity').checked})});renderUser();fillProfile();toast('Perfil e privacidade salvos com sucesso')}catch(err){toast(err.message,true)}};
$('#open-profile-advanced').onclick=openProfileAdvancedSettings;
$('#download-backup').onclick=async()=>{try{const headers={Authorization:'Bearer '+state.token};const res=await fetch(apiUrl('/backup'),{headers});if(!res.ok){let d={};try{d=await res.json()}catch{}throw new Error(d.detail||'Não foi possível criar o backup')}const blob=await res.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='niro-chat-backup.zip';document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Backup baixado. Guarde-o em local seguro.')}catch(err){toast(err.message,true)}};
$('#avatar-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const form=new FormData();form.append('file',file);try{const r=await api('/me/avatar',{method:'POST',body:form});state.user.avatar=r.avatar;renderUser();fillProfile();toast('Foto de perfil atualizada')}catch(err){toast(err.message,true)}e.target.value=''};
(async()=>{if(state.token){await enterApp();const params=new URLSearchParams(location.search);const invite=params.get('invite');if(invite){try{const r=await api('/communities/join/'+encodeURIComponent(invite),{method:'POST'});history.replaceState({},'',location.pathname);await loadCommunities();await openCommunity(r.community_id)}catch(e){toast(e.message,true)}}}})();
